data: {"type":"content_block_delta","index":1,"delta":{"type":"input_json_delta","partial_json":"{\"kind\": \"decision\", \"title\": \"Choose MIT or Apache-2.0 license for Acme Ltd\", \"body\": \"Simply put: MIT is a short permission notice. Apache-2.0 is longer but adds an express patent grant from contributors and a patent-retaliation clause.\\n\\nThe MIT LICENSE is committed on branch `add-mit-license` (commit 7024727), not yet pushed. If you switch to Apache-2.0, I'll replace the file, amend the commit, and keep the copyright line as \\\"Acme Ltd, 2026\\\".\\n\\nStakes: the license is hard to change later once others have contributed or used the code under it.\\n\\nOptions:\\n- Keep MIT: simplest, widely understood, no patent terms.\\n- Switch to Apache-2.0: explicit patent license from contributors. Better if Acme's work could involve patentable inventions.\\n\\nMy pick: Apache-2.0. As a company, the express patent grant protects Acme and its users more clearly than MIT's silence on patents.\", \"links\": [], \"actions\": [{\"kind\":\"resolve\",\"label\":\"Keep MIT\",\"recommended\":false},{\"kind\":\"resolve\",\"label\":\"Switch to Apache-2.0\",\"recommended\":true}], \"subscribe\": false}"}}

